import{_ as o,a0 as r,w as s,s as u,ao as x,I as t,x as l,a1 as a,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"11個Linux基礎面試問題 | LCTT x X-CMD","titleTemplate":false,"description":"11個Linux基礎面試問題 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"11個Linux基礎面試問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"11個Linux基礎面試問題 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/11 Basic Linux Interview Questions and Answers","title":"11個Linux基礎面試問題","tag":"201311","desc":""},"relativePath":"201311/11 Basic Linux Interview Questions and Answers.md","filePath":"[post].md"}'),d={name:"201311/11 Basic Linux Interview Questions and Answers.md"};function p(h,i,L,c,m,b){const n=r("Link");return s(),u("div",null,[i[11]||(i[11]=x('<h1 id="_11個linux基礎面試問題" tabindex="-1">11個Linux基礎面試問題 <a class="header-anchor" href="#_11個linux基礎面試問題" aria-label="Permalink to “11個Linux基礎面試問題”">​</a></h1><h3 id="q-1-linux-操作系統的核心是什麼" tabindex="-1">Q.1: Linux 操作系統的核心是什麼? <a class="header-anchor" href="#q-1-linux-操作系統的核心是什麼" aria-label="Permalink to “Q.1: Linux 操作系統的核心是什麼?”">​</a></h3><ul><li>Shell</li><li>Kernel</li><li>Command</li><li>Script</li><li>Terminal</li></ul><blockquote><p><strong>答</strong>: 內核(Kernel)是Linux 操作系統的核心。Shell是一個命令列解釋器，命令（Command）是針對計算機的指令，腳本(Script)是存儲在文件中的命令的集合，終端(Termial)是命令列接口。</p></blockquote><h3 id="q-2-linus-torvalds-都創建過什麼東東" tabindex="-1">Q.2: Linus Torvalds 都創建過什麼東東? <a class="header-anchor" href="#q-2-linus-torvalds-都創建過什麼東東" aria-label="Permalink to “Q.2: Linus Torvalds 都創建過什麼東東?”">​</a></h3><ul><li>Fedora</li><li>Slackware</li><li>Debian</li><li>Gentoo</li><li>Linux</li></ul><blockquote><p><strong>答</strong>: Linux Torvalds 創建了Linux，Linux是所有上述操作系統的核心，同樣也是其他一些Linux 操作系統的核心。</p></blockquote><h3 id="q-3-torvalds-使用c-語言編寫了linux內核的大部分代碼-是這樣嗎" tabindex="-1">Q.3: Torvalds，使用C++語言編寫了Linux內核的大部分代碼，是這樣嗎? <a class="header-anchor" href="#q-3-torvalds-使用c-語言編寫了linux內核的大部分代碼-是這樣嗎" aria-label="Permalink to “Q.3: Torvalds，使用C++語言編寫了Linux內核的大部分代碼，是這樣嗎?”">​</a></h3><blockquote><p><strong>答</strong>: 不! Linux內核包含了12,020,528行代碼，其中註釋佔去了2,151,595 行。因此剩下的9,868,933 行就是純代碼了。而其中7,896,318行都是用C語言寫的。</p></blockquote><p>剩下的1,972,615行則是使用C++，彙編，Perl, Shell Script, Python, Bash Script, HTML, awk, yacc, lex, sed等。</p><p><strong>注</strong>：代碼行數每天都在變動，平均每天超過3,509行代碼添加到內核。</p><h3 id="q-4-起初-linux-是為-intel-x86-架構編寫的-但是後來比其他操作系統移植的硬件平台都多-是這樣嗎" tabindex="-1">Q.4: 起初，Linux 是為 Intel X86 架構編寫的，但是後來比其他操作系統移植的硬件平台都多，是這樣嗎 ？ <a class="header-anchor" href="#q-4-起初-linux-是為-intel-x86-架構編寫的-但是後來比其他操作系統移植的硬件平台都多-是這樣嗎" aria-label="Permalink to “Q.4: 起初，Linux 是為 Intel X86 架構編寫的，但是後來比其他操作系統移植的硬件平台都多，是這樣嗎 ？”">​</a></h3><blockquote><p><strong>答</strong>: 是的，我同意。Linux那時候是為x86機器寫的，而且現已移至到所有類型的平台。今天超過90%的超級計算機都在使用Linux。Linux在移動手機和平板電腦領域前景廣闊。事實上我們被Linux包圍着，遠程遙控，太空科學，研究，Web，桌面計算等等，舉之不盡。</p></blockquote><h3 id="q-5-編輯-linux-內核合法嗎" tabindex="-1">Q.5: 編輯 Linux 內核合法嗎? <a class="header-anchor" href="#q-5-編輯-linux-內核合法嗎" aria-label="Permalink to “Q.5: 編輯 Linux 內核合法嗎?”">​</a></h3><blockquote><p><strong>答</strong>: 是的，內核基於GPL發佈，任何人都可以基於GPL允許的權限隨意編輯內核。Linux內核屬於免費開源軟件（FOSS）。</p></blockquote><h3 id="q-6-unix和linux操作系統-本質上的不同在哪裏" tabindex="-1">Q.6: UNIX和Linux操作系統，本質上的不同在哪裏？### <a class="header-anchor" href="#q-6-unix和linux操作系統-本質上的不同在哪裏" aria-label="Permalink to “Q.6: UNIX和Linux操作系統，本質上的不同在哪裏？###”">​</a></h3><blockquote><p><strong>答</strong>: Linux操作系統屬於免費開源軟件，內核是由 Linus Torvalds 和開源社區共同開發的。當然我們不能説UNIX操作系統和免費開源軟件（FOSS）無關，BSD 就是基於 FOSS 範疇的 UNIX 的變種。而且大公司如 Apple，IBM，Oracle，HP等，都在為UNIX內核貢獻代碼。</p></blockquote><h3 id="q-7-挑出來一個與眾不同的來" tabindex="-1">Q. 7: 挑出來一個與眾不同的來. <a class="header-anchor" href="#q-7-挑出來一個與眾不同的來" aria-label="Permalink to “Q. 7: 挑出來一個與眾不同的來.”">​</a></h3><ul><li>HP-UX</li><li>AIX</li><li>OSX</li><li>Slackware</li><li>Solaris</li></ul><blockquote><p><strong>答</strong> : Slackware。 HP-UX, AIX, OSX, Solaris 分別是由 HP, IBM, APPLE, Oracle 開發的，並且都是UNIX的變種. Slackware 則是一個Linux操作系統.</p></blockquote><h3 id="q-8-linux-不會感染病毒嗎" tabindex="-1">Q.8: Linux 不會感染病毒嗎? <a class="header-anchor" href="#q-8-linux-不會感染病毒嗎" aria-label="Permalink to “Q.8: Linux 不會感染病毒嗎?”">​</a></h3><blockquote><p><strong>答</strong> : 當然會! 這個地球上不存在不會感染病毒的操作系統。但是Linux以迄今為止病毒數量少而著稱，是的，甚至比UNIX還要少。Linux榜上有名的病毒只有60-100個，而且沒有一個病毒在傳播蔓延。Unix粗略估計有85-120個。</p></blockquote><h3 id="q-9-linux-屬於哪種類型的操作系統" tabindex="-1">Q.9: Linux 屬於哪種類型的操作系統? <a class="header-anchor" href="#q-9-linux-屬於哪種類型的操作系統" aria-label="Permalink to “Q.9: Linux 屬於哪種類型的操作系統?”">​</a></h3><ul><li>多用户</li><li>多任務</li><li>多線程</li><li>以上所有</li><li>以上都不是</li></ul><blockquote><p><strong>答</strong> : 以上所有。Linux是一個支持多用户，可以同時運行多個進程執行多個任務的操作系統。</p></blockquote><h3 id="q-10-一般的-linux-命令的語法格式是" tabindex="-1">Q.10: 一般的 Linux 命令的語法格式是： <a class="header-anchor" href="#q-10-一般的-linux-命令的語法格式是" aria-label="Permalink to “Q.10: 一般的 Linux 命令的語法格式是：”">​</a></h3><ul><li>command [選項] [參數]</li><li>command 選項 [參數]</li><li>command [選項] [參數]</li><li>command 選項 參數</li></ul><blockquote><p><strong>答</strong> : Linux 命令的正確語法是, Command [選項] [參數]。</p></blockquote><h3 id="q-11-挑出來一個與眾不同的來" tabindex="-1">Q.11: 挑出來一個與眾不同的來. <a class="header-anchor" href="#q-11-挑出來一個與眾不同的來" aria-label="Permalink to “Q.11: 挑出來一個與眾不同的來.”">​</a></h3><ul><li>Vi</li><li>vim</li><li>cd</li><li>nano</li></ul><blockquote><p><strong>答</strong> : cd 與其他命令不同。Vi，vim和 nano都是編輯器，用於編輯文檔，而cd是用於切換目錄的命令。</p></blockquote><p>就這麼多了。上述問題你學到手幾個？效果如何？我們期待着你的評論。下週，會有新的問題，讓我們拭目以待。保持健康，鎖定鏈接，記得來<strong>Tecmint</strong>哦。</p><hr>',33)),t("p",null,[i[1]||(i[1]=l("via: ",-1)),a(n,{href:"http://www.tecmint.com/basic-linux-interview-questions-and-answers/"},{default:e(()=>[...i[0]||(i[0]=[l("http://www.tecmint.com/basic-linux-interview-questions-and-answers/",-1)])]),_:1})]),t("p",null,[i[4]||(i[4]=l("譯者：",-1)),a(n,{href:"https://github.com/l3b2w1"},{default:e(()=>[...i[2]||(i[2]=[l("l3b2w1",-1)])]),_:1}),i[5]||(i[5]=l(" 校對：",-1)),a(n,{href:"https://github.com/jasminepeng"},{default:e(()=>[...i[3]||(i[3]=[l("jasminepeng",-1)])]),_:1})]),t("p",null,[i[8]||(i[8]=l("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[6]||(i[6]=[l("LCTT",-1)])]),_:1}),i[9]||(i[9]=l(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:e(()=>[...i[7]||(i[7]=[l("Linux中國",-1)])]),_:1}),i[10]||(i[10]=l(" 榮譽推出",-1))])])}const T=o(d,[["render",p]]);export{g as __pageData,T as default};
